#include <iostream>

class Base {
public:
    virtual const char* name() const noexcept = 0;  // Pure virtual function; compiler adds to vtable
};

class Derived : public Base {
public:
    const char* name() const noexcept override { return "Derived"; }  // Overrides base; compiler updates vtable entry
};

int main() {
    Base* ptr = new Derived();  // Points to Derived object; runtime type is Derived
    std::cout << ptr->name() << std::endl;  // Virtual call: compiler generates code to use vptr and vtable
    delete ptr;
    return 0;
}
